-- Real UNIOSUN faculty/department/course data, provided directly by the founder
-- (sourced from the SUG), replacing the 'known gap' flagged in the earlier
-- automated import (that import correctly refused to guess this data).
--
-- Judgment call: 'Communication & Media Studies' courses are attached to the
-- existing 'College of Humanities and Culture' faculty, since no separate
-- college for it exists in the 7-college structure already in the database
-- and it wasn't listed in the 6-campus mapping either. If UNIOSUN actually runs
-- this as its own distinct college, split it out later -- flagging rather than
-- guessing silently.

alter table faculties add column if not exists campus text;

update faculties set campus = 'Osogbo' where name = 'College of Health Sciences' and university_id = (select id from universities where name = 'Osun State University');
update faculties set campus = 'Osogbo' where name = 'College of Science, Engineering and Technology' and university_id = (select id from universities where name = 'Osun State University');
update faculties set campus = 'Okuku' where name = 'College of Management and Social Sciences' and university_id = (select id from universities where name = 'Osun State University');
update faculties set campus = 'Ikire' where name = 'College of Humanities and Culture' and university_id = (select id from universities where name = 'Osun State University');
update faculties set campus = 'Ejigbo' where name = 'College of Agriculture' and university_id = (select id from universities where name = 'Osun State University');
update faculties set campus = 'Ifetedo' where name = 'College of Law' and university_id = (select id from universities where name = 'Osun State University');
update faculties set campus = 'Ipetu-Ijesa' where name = 'College of Education' and university_id = (select id from universities where name = 'Osun State University');


